/// One text style: a point size and a weight.
public struct HubFontSpec: Sendable, Equatable {
    public var size: CGFloat
    public var weight: Font.Weight

    public init(size: CGFloat, weight: Font.Weight = .regular) {
        self.size = size
        self.weight = weight
    }

    /// The SwiftUI font. Uses the system font; a bundled font is a RightKit theme decision.
    public var font: Font { Font.system(size: size, weight: weight) }
}

/// Type sizes, from the font sizes in shell.visual.css.
public struct HubTypeScale: Sendable, Equatable {
    /// Page heading (`.rk-page__head h1`, 22 pt).
    public var pageTitle = HubFontSpec(size: 22, weight: .semibold)
    /// Top bar title (`.rk-top__title`, 15 pt).
    public var title = HubFontSpec(size: 15, weight: .bold)
    /// Descriptions under a heading (13.5 pt).
    public var lead = HubFontSpec(size: 13.5)
    /// Body and sidebar rows (13 pt).
    public var body = HubFontSpec(size: 13)
    /// Field and segment labels (12.5 pt, semibold).
    public var label = HubFontSpec(size: 12.5, weight: .semibold)
    /// Secondary text (12 pt).
    public var caption = HubFontSpec(size: 12)
    /// Status text and pills (11.5 pt).
    public var small = HubFontSpec(size: 11.5)
    /// Group headings and badges (11 pt, semibold).
    public var micro = HubFontSpec(size: 11, weight: .semibold)
    /// Large numbers in stat tiles.
    public var stat = HubFontSpec(size: 22, weight: .semibold)

    public init() {}
}

