/// How the header title is drawn. The default is the type scale's `title` (15 pt bold). An app with
/// a display face sets its own: a bundled font by name (the host registers the file), or the system
/// font in a width and weight, and whether the shell uppercases the text.
///
/// Held as plain values (not a `Font`) so the theme stays `Sendable` and `Equatable`.
public struct HubTitleStyle: Sendable, Equatable {
    public var size: CGFloat
    public var weight: Font.Weight
    /// The system font's condensed width. Ignored when `fontName` is set.
    public var condensed: Bool
    /// A font the host has registered, by name (`Font.custom`). Nil uses the system font.
    public var fontName: String?
    /// Whether the shell writes the title in capitals (the strings are uppercased, not styled).
    public var uppercase: Bool

    public init(
        size: CGFloat = 15,
        weight: Font.Weight = .bold,
        condensed: Bool = false,
        fontName: String? = nil,
        uppercase: Bool = false
    ) {
        self.size = size
        self.weight = weight
        self.condensed = condensed
        self.fontName = fontName
        self.uppercase = uppercase
    }

    /// The SwiftUI font.
    public var font: Font {
        if let fontName { return Font.custom(fontName, size: size) }
        let base = Font.system(size: size, weight: weight)
        return condensed ? base.width(.condensed) : base
    }

    /// The text to draw for a title.
    public func text(_ title: String) -> String {
        uppercase ? title.uppercased() : title
    }
}

/// The design tokens the hub draws with. Components read the theme from the environment
/// (`\.hubTheme`); `HubShell` sets it from its `HubContext`.
public struct HubTheme: Sendable, Equatable {
    public var light: HubPalette
    public var dark: HubPalette
    public var type: HubTypeScale
    public var spacing: HubSpacing
    public var radii: HubRadii
    public var motion: HubMotion
    public var layout: HubLayout
    /// The header title style.
    public var headerTitle: HubTitleStyle

    public init(
        light: HubPalette = .light,
        dark: HubPalette = .dark,
        type: HubTypeScale = HubTypeScale(),
        spacing: HubSpacing = HubSpacing(),
        radii: HubRadii = HubRadii(),
        motion: HubMotion = HubMotion(),
        layout: HubLayout = HubLayout(),
        headerTitle: HubTitleStyle = HubTitleStyle()
    ) {
        self.light = light
        self.dark = dark
        self.type = type
        self.spacing = spacing
        self.radii = radii
        self.motion = motion
        self.layout = layout
        self.headerTitle = headerTitle
    }

    /// The suite defaults.
    public static let standard = HubTheme()

    /// The token names a brand file may override (`OVERRIDABLE_TOKENS` in `@rightkit/theme`).
    public static let overridableTokens: [String] = [
        "chrome", "plane", "elevated", "panel", "sunk", "ink", "ink-2", "ink-3", "ok", "warn", "bad",
        "ok-dot", "warn-dot", "line", "line-strong", "hairline", "accent-ink",
    ]

    /// The palette for an appearance.
    public func palette(_ scheme: ColorScheme) -> HubPalette {
        scheme == .dark ? dark : light
    }
}

private struct HubThemeKey: EnvironmentKey {
    static let defaultValue = HubTheme.standard
}

public extension EnvironmentValues {
    /// The hub's design tokens. `HubShell` sets this; components read it.
    var hubTheme: HubTheme {
        get { self[HubThemeKey.self] }
        set { self[HubThemeKey.self] = newValue }
    }
}
